pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: call Initialized to unlock Collect; set MinSum low enough
        c.SetMinSum(0.5 ether);
        c.Initialized();

        // Alice deposits 1 ether
        address alice = address(0xABCD);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Deposit{value: 1 ether}();

        // Bob (different address) deposits 2 ether
        address bob = address(0x1234);
        vm.deal(bob, 2 ether);
        vm.prank(bob);
        c.Deposit{value: 2 ether}();

        // Bob calls Collect(1 ether) – he has balance >= MinSum and >= _am
        vm.prank(bob);
        c.Collect(1 ether);

        // In the reference, Bob's balance should be 2 ether - 1 ether = 1 ether
        // In the buggy version (addition), Bob's balance becomes 2 ether + 1 ether = 3 ether
        assertTrue(c.balances(bob) == 1 ether);
    }
}

